import re
from typing import Annotated

from pydantic import AfterValidator, BaseModel, ConfigDict, Field, StrictStr, StringConstraints, field_validator

from app.config import get_settings
from app.money import parse_amount_to_cents

_UUID_RE = re.compile(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", re.IGNORECASE)


def _normalize_uuid(value: str) -> str:
    if not _UUID_RE.fullmatch(value):
        raise ValueError("must be a UUID like '3f1c9a2e-7b4d-4c1e-9a55-2d8e6f0b7c41'")
    return value.lower()


def _validate_amount(value: str) -> str:
    parse_amount_to_cents(value)
    return value


FirmUuid = Annotated[StrictStr, AfterValidator(_normalize_uuid)]
Amount = Annotated[StrictStr, AfterValidator(_validate_amount)]
Description = Annotated[StrictStr, StringConstraints(strip_whitespace=True, min_length=1, max_length=1000)]


class PaymentIn(BaseModel):
    model_config = ConfigDict(extra="forbid")

    amount: Amount
    payee_firm_uuid: FirmUuid
    description: Description

    @property
    def amount_cents(self) -> int:
        return parse_amount_to_cents(self.amount)


class BulkPaymentIn(BaseModel):
    model_config = ConfigDict(extra="forbid")

    payer_firm_uuid: FirmUuid
    payments: list[PaymentIn] = Field(min_length=1)

    @field_validator("payments")
    @classmethod
    def _limit_payment_count(cls, payments: list[PaymentIn]) -> list[PaymentIn]:
        limit = get_settings().max_payments_per_request
        if len(payments) > limit:
            raise ValueError(f"at most {limit} payments per request")
        return payments

    @property
    def total_amount_cents(self) -> int:
        return sum(p.amount_cents for p in self.payments)


class PaymentOut(BaseModel):
    id: int
    payee_firm_uuid: str
    amount_cents: int
    description: str


class BulkPaymentOut(BaseModel):
    payer_firm_uuid: str
    total_amount_cents: int
    payments: list[PaymentOut]

