        "payer_firm_uuid": LOPEZ,
        "payments": [
            {"amount": "300", "payee_firm_uuid": NAIR, "description": "a"},
            {"amount": "200.01", "payee_firm_uuid": PINECREST, "description": "b"},
        ],
    }
    resp = post(client, body)

