    # The app's DB timeouts (lock 5 s, statement 15 s, pool 10 s) end every request well before this.
    proxy_read_timeout 60s;

    # Errors nginx produces itself use the API's {"error": ...} shape instead of HTML.
    error_page 413 @payload_too_large;
    error_page 502 @bad_gateway;
    error_page 504 @gateway_timeout;

    location / {
        proxy_pass http://app;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        # Without "non_idempotent", a POST that already reached an instance is never resent to the other one,
        # so a slow bulk payment can't be applied twice.
        proxy_next_upstream error timeout;
    }

    location @payload_too_large {
        default_type application/json;
        return 413 '{"error":{"code":"payload_too_large","message":"Request body exceeds 2 MB."}}\n';
    }

    location @bad_gateway {
        default_type application/json;
        add_header Retry-After 1 always;
        return 502 '{"error":{"code":"bad_gateway","message":"No app instance could take the request. Nothing was applied; retry."}}\n';
    }

    location @gateway_timeout {
        default_type application/json;
        return 504 '{"error":{"code":"gateway_timeout","message":"The outcome is unknown. Retry with the same Idempotency-Key to avoid paying twice."}}\n';
    }
}

